typedef float float8 __attribute__((vector_size(32)));

static inline float8 load8(const float *p) {
    float8 value;
    std::memcpy(&value, p, sizeof(value));
    return value;
}

static inline void store8(float *p, float8 value) {
    std::memcpy(p, &value, sizeof(value));
}

static void stencil_step(int x0, int x1, int y0, int y1, int z0, int z1, int Nx, int Ny, int Nz, const float *__restrict__ coef,
                         const float *__restrict__ vsq, const float *__restrict__ Ain, float *__restrict__ Aout) {
    int Nxy = Nx * Ny;

    for (int z = z0; z < z1; ++z) {
        for (int y = y0; y < y1; ++y) {
            int x = x0;
            for (; x1 - x >= 8; x += 8) {
                int index = (z * Nxy) + (y * Nx) + x;
                float8 center = load8(Ain + index);
                float8 div = coef[0] * center +
                             coef[1] * (load8(Ain + index + 1) + load8(Ain + index - 1) +
                                        load8(Ain + index + Nx) + load8(Ain + index - Nx) +
                                        load8(Ain + index + Nxy) + load8(Ain + index - Nxy)) +
                             coef[2] * (load8(Ain + index + 2) + load8(Ain + index - 2) +
                                        load8(Ain + index + 2 * Nx) + load8(Ain + index - 2 * Nx) +
                                        load8(Ain + index + 2 * Nxy) + load8(Ain + index - 2 * Nxy)) +
                             coef[3] * (load8(Ain + index + 3) + load8(Ain + index - 3) +
                                        load8(Ain + index + 3 * Nx) + load8(Ain + index - 3 * Nx) +
                                        load8(Ain + index + 3 * Nxy) + load8(Ain + index - 3 * Nxy));
                float8 next = 2.0f * center - load8(Aout + index) + load8(vsq + index) * div;
                store8(Aout + index, next);
            }
            for (; x < x1; ++x) {
                int index = (z * Nxy) + (y * Nx) + x;
#define A_cur(x, y, z) Ain[index + (x) + ((y)*Nx) + ((z)*Nxy)]
#define A_next(x, y, z) Aout[index + (x) + ((y)*Nx) + ((z)*Nxy)]
                float div = coef[0] * A_cur(0, 0, 0) +
                            coef[1] * (A_cur(+1, 0, 0) + A_cur(-1, 0, 0) + A_cur(0, +1, 0) + A_cur(0, -1, 0) +
                                       A_cur(0, 0, +1) + A_cur(0, 0, -1)) +
                            coef[2] * (A_cur(+2, 0, 0) + A_cur(-2, 0, 0) + A_cur(0, +2, 0) + A_cur(0, -2, 0) +
                                       A_cur(0, 0, +2) + A_cur(0, 0, -2)) +
                            coef[3] * (A_cur(+3, 0, 0) + A_cur(-3, 0, 0) + A_cur(0, +3, 0) + A_cur(0, -3, 0) +
                                       A_cur(0, 0, +3) + A_cur(0, 0, -3));

                A_next(0, 0, 0) = 2 * A_cur(0, 0, 0) - A_next(0, 0, 0) + vsq[index] * div;
#undef A_cur
#undef A_next
            }
        }
    }
}

